python3 -c "
import json
with open('/app/resources/treasury_bulletin_1994_06.json') as f:
    d = json.load(f)

# Search for CPI-related content
def find_cpi(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'cpi' in k.lower():
                print(f'{path}.{k}: {v}')
            find_cpi(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_cpi(item, f'{path}[{i}]')

find_cpi(d)
"

python3 -c "
import json
with open('/app/resources/treasury_bulletin_1995_06.json') as f:
    d = json.load(f)

# Find tables with interest-bearing debt 
def find_tables(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'interest' in str(k).lower() or 'debt' in str(k).lower() or 'series' in str(k).lower():
                print(f'{path}.{k}: {str(v)[:200]}')
            find_tables(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_tables(item, f'{path}[{i}]')

find_tables(d)
"

python3 -c "
import json
with open('/app/resources/treasury_bulletin_1995_06.json') as f:
    d = json.load(f)

# Search for 166731 (the 1994 calendar year debt value)
def find_value(obj, target, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if str(target) in str(v):
                print(f'Found {target} at {path}.{k}: {str(v)[:300]}')
            find_value(v, target, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_value(item, target, f'{path}[{i}]')

find_value(d, '166731')
"

